sql_query:
SELECT "Number of arms"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Number of arms", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Name of ICI", '')) = 'Ipilimumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Number of arms" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Number of arms", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Name of ICI", '')) = 'Ipilimumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_arm_category(source_value) AS "arm_category"
FROM base;
